<template>
  <section class="invited-events" aria-labelledby="invited-events-title">
    <div class="invited-heading"><div><span class="invited-kicker">YOUR INVITATIONS</span><h4 id="invited-events-title">A place on the guest list</h4></div></div>
    <div class="invited-tabs" role="tablist" aria-label="Your event invitations"><button type="button" role="tab" :aria-selected="view === 'invited'" :class="{active:view === 'invited'}" @click="view = 'invited'; expanded = false">Invited events <span>{{ activeEvents.length }}</span></button><button type="button" role="tab" :aria-selected="view === 'declined'" :class="{active:view === 'declined'}" @click="view = 'declined'; expanded = false">Declined events <span>{{ declinedEvents.length }}</span></button></div>
    <label class="invited-search"><span class="sr-only">Search your event invitations</span><input v-model="search" type="search" placeholder="Search event, location or details…" aria-label="Search your event invitations" /></label>
    <p v-if="notice" role="status" class="invited-notice">{{ notice }}</p><p v-if="error" role="alert" class="invited-error">{{ error }}</p>
    <p v-if="view === 'declined' && declinedEvents.length" class="invited-help">These invitations remain available. You can change your RSVP whenever your plans change.</p>
    <ul v-if="displayed.length" class="invited-list"><li v-for="event in displayed" :key="event.id" class="invited-event"><div class="invited-event-heading"><div><a :href="eventUrl(event)" class="invited-event-name">{{ event.title || 'Company event' }}</a><div class="invited-event-meta">{{ eventWhen(event) }}</div><div v-if="event.eventLocationName || event.eventLocationAddress" class="invited-event-meta">{{ [event.eventLocationName,event.eventLocationAddress].filter(Boolean).join(' · ') }}</div></div><span class="rsvp-status" :class="rsvp(event) || 'unanswered'">{{ responseLabel(rsvp(event)) }}</span></div><div class="invited-event-footer"><div class="invited-tags"><span>{{ event.mandatory ? 'Mandatory attendance' : 'Optional invitation' }}</span><span v-if="event.potluckEnabled">Potluck</span></div><a :href="eventUrl(event)" class="invited-open">Details, votes &amp; RSVP ↗</a></div><div v-if="event.canRsvp !== false" class="rsvp-controls" :aria-label="`Your RSVP for ${event.title}`"><span>{{ savingId === Number(event.id) ? 'Saving…' : rsvp(event) ? 'Change RSVP' : 'Will you attend?' }}</span><div><button v-for="option in responseOptions" :key="option.value" type="button" :class="{selected:rsvp(event) === option.value}" :aria-pressed="rsvp(event) === option.value" :disabled="savingId !== null" @click="respond(event,option.value)">{{ option.label }}</button></div></div></li></ul>
    <p v-else class="invited-empty">{{ search ? 'No invitations match your search.' : view === 'declined' ? 'You haven’t declined any current event invitations.' : 'No current invitations in this list. Declined events remain available in their own tab.' }}</p>
    <button v-if="!search && !expanded && filtered.length > displayLimit" type="button" class="show-more-events" @click="expanded = true">Show all {{ filtered.length }} {{ view === 'declined' ? 'declined' : 'invited' }} events</button>
  </section>
</template>
<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import api from '../../services/api';
import { formatBusinessDateTime } from '../../utils/timezones';
import { notifyCompanyEventRsvpChanged, onCompanyEventRsvpChanged } from '../../utils/companyEventRsvpEvents';
const props=defineProps({events:{type:Array,default:()=>[]}});
const emit=defineEmits(['changed']);
const responseOptions=[{value:'yes',label:'Yes'},{value:'maybe',label:'Maybe'},{value:'no',label:'No'}];
const view=ref('invited'),search=ref(''),expanded=ref(false),savingId=ref(null),error=ref(''),notice=ref(''),overrides=ref(new Map());
const displayLimit=5;
function savedRsvp(event){const raw=String(event.myRsvp ?? event.myResponse?.responseKey ?? event.myResponse?.response_key ?? event.myResponse?.key ?? event.myResponse?.responseLabel ?? '').trim().toLowerCase();return ({y:'yes',yes:'yes',n:'no',no:'no',m:'maybe',maybe:'maybe'})[raw]||null;}
const rsvp=event=>overrides.value.has(Number(event.id))?overrides.value.get(Number(event.id)):savedRsvp(event);
const responseLabel=value=>({yes:'Going',maybe:'Maybe',no:'Declined'})[value]||'RSVP requested';
const activeEvents=computed(()=>props.events.filter(e=>rsvp(e)!=='no'));
const declinedEvents=computed(()=>props.events.filter(e=>rsvp(e)==='no'));
const filtered=computed(()=>{const term=search.value.trim().toLocaleLowerCase();return [...(view.value==='declined'?declinedEvents.value:activeEvents.value)].filter(event=>!term||[event.title,event.description,event.eventLocationName,event.eventLocationAddress,event.agencyName,...(event.invitedAgencyNames||[])].join(' ').toLocaleLowerCase().includes(term)).sort((a,b)=>{const time=e=>e.dateToBeDecided||!e.startsAt?Infinity:new Date(e.nextOccurrenceStart||e.startsAt).getTime();return time(a)-time(b)||String(a.title||'').localeCompare(String(b.title||''));});});
const displayed=computed(()=>expanded.value||search.value.trim()?filtered.value:filtered.value.slice(0,displayLimit));
const eventUrl=event=>event.staffPageUrl||`/staff-events/${event.id}${event.agencyId?`?agencyId=${Number(event.agencyId)}`:''}`;
const eventWhen=event=>event.dateToBeDecided||!event.startsAt?'Date & time to be decided':formatBusinessDateTime(event.nextOccurrenceStart||event.startsAt,event.timezone);
async function respond(event,response){if(savingId.value!==null||rsvp(event)===response)return;savingId.value=Number(event.id);error.value='';notice.value='';try{await api.post(`/me/company-events/${event.id}/respond`,{response,agencyId:event.agencyId},{params:{agencyId:event.agencyId},skipGlobalLoading:true});overrides.value=new Map(overrides.value).set(Number(event.id),response);notice.value=response==='no'?'Your RSVP was saved. This invitation moved to Declined events, where you can change it later.':event.dateToBeDecided||!event.startsAt?'Your RSVP was saved. This invitation stays here; it will appear on your schedule once a date is set.':`Your RSVP was saved as ${response==='yes'?'Yes':'Maybe'}. This event is in your invited events and your schedule.`;if(response!=='no'&&view.value==='declined')view.value='invited';notifyCompanyEventRsvpChanged({eventId:Number(event.id),agencyId:Number(event.agencyId),response});emit('changed',{eventId:Number(event.id),response});}catch(e){error.value=e.response?.data?.error?.message||'Could not save your RSVP. Your previous response is unchanged.';}finally{savingId.value=null;}}
let unsubscribe;
onMounted(()=>{unsubscribe=onCompanyEventRsvpChanged(detail=>{if(props.events.some(e=>Number(e.id)===Number(detail.eventId)))overrides.value=new Map(overrides.value).set(Number(detail.eventId),detail.response);});});
onBeforeUnmount(()=>unsubscribe?.());
watch(()=>props.events,events=>{
  const pending=new Map(overrides.value);
  for(const [id,response] of pending){
    const event=events.find(item=>Number(item.id)===id);
    // A calendar refresh can settle before the invitation-list refresh. Keep
    // the confirmed local response until that list acknowledges it.
    if(!event||savedRsvp(event)===response)pending.delete(id);
  }
  overrides.value=pending;
});
</script>
<style scoped>
.invited-events{border:1px solid #d8e4da;border-radius:12px;padding:16px;margin-bottom:18px;background:#fbfdf9;color:#294c39}.invited-heading h4{font-size:17px;margin:5px 0 14px;font-weight:650;letter-spacing:-.02em}.invited-kicker{font-size:12px;letter-spacing:.12em;font-weight:700;color:#57795e}.invited-tabs{display:flex;gap:5px;padding:4px;border:1px solid #dce6d8;border-radius:8px;background:#eff5eb;margin-bottom:12px}.invited-tabs button{display:flex;align-items:center;justify-content:center;gap:7px;flex:1;border:0;border-radius:5px;background:none;padding:9px 6px;font:inherit;font-size:12px;color:#57784b;cursor:pointer}.invited-tabs button.active{background:#fff;box-shadow:0 1px 4px #2c56361c;color:#2e5f38;font-weight:650}.invited-tabs button span{background:#e8f0e1;border-radius:20px;padding:1px 6px;font-size:12px}.invited-search input{width:100%;box-sizing:border-box;border:1px solid #cbdac7;border-radius:8px;padding:10px 11px;font:inherit;font-size:13px;background:white;color:#375e3b}.invited-search input::placeholder{color:#71816c}.invited-list{list-style:none;margin:14px 0 0;padding:0;display:grid;gap:12px}.invited-event{border:1px solid #dce6d7;border-radius:10px;padding:14px;background:#fff}.invited-event-heading{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.invited-event-name{font-size:14px;color:#2c5637;font-weight:650;text-decoration:none;line-height:1.5}.invited-event-name:hover{text-decoration:underline}.invited-event-meta{font-size:12px;color:#64785c;line-height:1.65;margin-top:4px}.rsvp-status{flex:none;background:#f3f5ed;border:1px solid #e0e5d4;color:#65774f;padding:3px 7px;border-radius:20px;font-size:12px;font-weight:650;white-space:nowrap}.rsvp-status.yes{background:#eaf5e4;color:#3b6632;border-color:#cfe1c3}.rsvp-status.maybe{background:#fff8e7;color:#826a2f;border-color:#ebdfba}.rsvp-status.no{background:#f1f2ed;color:#707565;border-color:#e0e3d8}.invited-event-footer{display:flex;gap:8px;justify-content:space-between;align-items:center;flex-wrap:wrap;margin-top:12px}.invited-tags{display:flex;gap:5px;flex-wrap:wrap}.invited-tags span{font-size:12px;color:#697a5a;background:#f5f7f1;border-radius:4px;padding:3px 5px}.invited-open{font-size:12px;font-weight:600;color:#476f3c;text-decoration:none}.invited-open:hover{text-decoration:underline}.rsvp-controls{display:flex;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid #e7ede1;margin-top:12px;padding-top:12px}.rsvp-controls>span{font-size:12px;color:#6e7f60}.rsvp-controls>div{display:flex;gap:5px}.rsvp-controls button{border:1px solid #ccdac0;background:#fff;color:#597847;padding:7px 11px;border-radius:6px;font:inherit;font-size:13px;cursor:pointer}.rsvp-controls button.selected{background:#466f3b;color:#fff;border-color:#466f3b}.rsvp-controls button:disabled{opacity:.6;cursor:default}.invited-empty,.invited-help{font-size:12px;line-height:1.6;color:#687d5b;margin:14px 0 0}.invited-notice{font-size:12px;line-height:1.6;padding:11px;border:1px solid #cddfc3;background:#edf6e7;color:#46663b;border-radius:8px}.invited-error{font-size:12px;line-height:1.6;padding:11px;background:#fff1eb;color:#963f2c;border:1px solid #e8c6b7;border-radius:8px}.show-more-events{border:0;background:none;color:#4d743e;font:inherit;font-size:12px;font-weight:650;cursor:pointer;display:block;margin:14px auto 0}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}[data-theme=dark] .invited-events{background:#1e2a21;border-color:#3b5140;color:#d5e4cd}[data-theme=dark] .invited-event{background:#253328;border-color:#43573e}[data-theme=dark] .invited-event-name,[data-theme=dark] .invited-open{color:#c1dfb2}[data-theme=dark] .invited-event-meta,[data-theme=dark] .invited-empty,[data-theme=dark] .invited-help{color:#a9bba0}@media(max-width:420px){.invited-events{padding:12px}.invited-event{padding:12px}.invited-event-heading{flex-direction:column}.rsvp-controls{flex-direction:column;align-items:flex-start}.rsvp-controls>div{width:100%}.rsvp-controls button{flex:1}.invited-tabs button{font-size:12px}}
</style>
